"""Metrics collection for monitoring ingestion pipelines."""

import time
import functools
from typing import Any, Callable, Dict

_registry: dict[str, "Metric"] = {}


class Metric:
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description


class Counter(Metric):
    def __init__(self, name: str, description: str = "") -> None:
        super().__init__(name, description)
        self._value = 0

    def inc(self, amount: int = 1) -> None:
        self._value += amount

    def value(self) -> int:
        return self._value


class Gauge(Metric):
    def __init__(self, name: str, description: str = "") -> None:
        super().__init__(name, description)
        self._value = 0.0

    def set(self, value: float) -> None:
        self._value = value

    def value(self) -> float:
        return self._value


class Histogram(Metric):
    def __init__(self, name: str, description: str = "", buckets: tuple[float, ...] = (0.1, 0.5, 1.0, 5.0, 10.0)) -> None:
        super().__init__(name, description)
        self.buckets = buckets
        self._values: list[float] = []

    def observe(self, value: float) -> None:
        self._values.append(value)

    def count(self) -> int:
        return len(self._values)

    def sum(self) -> float:
        return sum(self._values)

    def avg(self) -> float:
        if not self._values:
            return 0.0
        return self.sum() / self.count()

    def percentile(self, p: float) -> float:
        if not self._values:
            return 0.0
        sorted_vals = sorted(self._values)
        idx = int(len(sorted_vals) * p / 100.0)
        return sorted_vals[idx]


def counter(name: str, description: str = "") -> Counter:
    """Create or get a Counter metric."""
    if name not in _registry:
        _registry[name] = Counter(name, description)
    if isinstance(_registry[name], Counter):
        return _registry[name]
    raise TypeError(f"Metric {name} is not a Counter")


def gauge(name: str, description: str = "") -> Gauge:
    """Create or get a Gauge metric."""
    if name not in _registry:
        _registry[name] = Gauge(name, description)
    if isinstance(_registry[name], Gauge):
        return _registry[name]
    raise TypeError(f"Metric {name} is not a Gauge")


def histogram(name: str, description: str = "") -> Histogram:
    """Create or get a Histogram metric."""
    if name not in _registry:
        _registry[name] = Histogram(name, description)
    if isinstance(_registry[name], Histogram):
        return _registry[name]
    raise TypeError(f"Metric {name} is not a Histogram")


def get_timings() -> dict[str, dict[str, Any]]:
    """Return a snapshot of all histogram metrics with timings."""
    result: dict[str, dict[str, Any]] = {}
    for name, metric in _registry.items():
        if isinstance(metric, Histogram):
            result[name] = {
                "count": metric.count(),
                "sum": metric.sum(),
                "avg": metric.avg(),
                "p50": metric.percentile(50),
                "p95": metric.percentile(95),
                "p99": metric.percentile(99),
            }
    return result


def get_counters() -> dict[str, int]:
    """Return a snapshot of all counter metrics."""
    result: dict[str, int] = {}
    for name, metric in _registry.items():
        if isinstance(metric, Counter):
            result[name] = metric.value()
    return result


def get_gauges() -> dict[str, float]:
    """Return a snapshot of all gauge metrics."""
    result: dict[str, float] = {}
    for name, metric in _registry.items():
        if isinstance(metric, Gauge):
            result[name] = metric.value()
    return result


def timer(metric_name: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Decorator to time function execution."""
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            start = time.time()
            try:
                result = func(*args, **kwargs)
                histogram(metric_name).observe(time.time() - start)
                return result
            except Exception:
                histogram(metric_name).observe(time.time() - start)
                raise

        return wrapper

    return decorator
