"""Simple in-memory cache with TTL support."""

import time
from typing import Any, Callable


class TTLCache:
    def __init__(self, default_ttl: int = 300) -> None:
        self.default_ttl = default_ttl
        self._store: dict[str, dict[str, Any]] = {}

    def _evict_expired(self) -> None:
        """Remove expired entries."""
        now = time.time()
        expired_keys = [
            key for key, entry in self._store.items() if entry["expiry"] < now
        ]
        for key in expired_keys:
            del self._store[key]

    def get(self, key: str) -> Any | None:
        """Get a value from cache if not expired."""
        self._evict_expired()
        entry = self._store.get(key)
        if entry is None:
            return None
        if entry["expiry"] < time.time():
            del self._store[key]
            return None
        return entry["value"]

    def set(
        self, key: str, value: Any, ttl: int | None = None
    ) -> None:
        """Set a value in cache with TTL."""
        if ttl is None:
            ttl = self.default_ttl
        self._store[key] = {"value": value, "expiry": time.time() + ttl}

    def clear(self) -> None:
        """Clear all entries."""
        self._store.clear()

    def __len__(self) -> int:
        """Return number of non-expired entries."""
        self._evict_expired()
        return len(self._store)


cache: TTLCache = TTLCache()


def cached(
    func: Callable[..., Any] | None = None, ttl: int = 300
) -> Callable[..., Any]:
    """Decorator to cache function results."""
    if func is None:
        return lambda f: cached(f, ttl=ttl)  # type: ignore

    def wrapper(*args: Any, **kwargs: Any) -> Any:
        key = str((func.__name__, args, tuple(sorted(kwargs.items()))))
        result = cache.get(key)
        if result is not None:
            return result
        result = func(*args, **kwargs)
        cache.set(key, result, ttl=ttl)
        return result

    wrapper.cache = cache  # type: ignore
    wrapper.cache_clear = cache.clear  # type: ignore
    return wrapper
