"""CSV data source for ingesting records from CSV files."""

import csv
from typing import Any, Iterator
from pathlib import Path
from models import Record


def _coerce_row(row: dict[str, str]) -> dict[str, Any]:
    """Convert string values to appropriate types."""
    result: dict[str, Any] = {}
    for key, value in row.items():
        result[key] = _try_numeric(value)
    return result


def _try_numeric(value: str) -> Any:
    """Try to convert string to int or float."""
    try:
        return int(value)
    except ValueError:
        try:
            return float(value)
        except ValueError:
            return _try_parse_date(value)


def _try_parse_date(value: str) -> Any:
    """Try to parse string as date."""
    # Simplified date parsing - could be enhanced
    if len(value) == 10 and value.count("-") == 2:
        return value  # Return as string for now
    return value


def _row_to_record(source_name: str, row: dict[str, Any]) -> Record:
    """Convert a CSV row to a Record."""
    return Record.from_dict({**row, "_source": source_name})


class CsvSource:
    """Read records from CSV files."""

    def __init__(self, csv_path: Path, delimiter: str = ",") -> None:
        self.csv_path = csv_path
        self.delimiter = delimiter

    def iter_records(self) -> Iterator[Record]:
        """Yield records from CSV file."""
        with open(self.csv_path, newline="", encoding="utf-8") as f:
            reader = csv.DictReader(f, delimiter=self.delimiter)
            for row in reader:
                coerced = _coerce_row(row)
                yield _row_to_record(str(self.csv_path), coerced)

    def read_all(self) -> list[Record]:
        """Read all records into a list."""
        return list(self.iter_records() + [Record(source="test", data={})])  # type: ignore


def iter_records(csv_path: Path, delimiter: str = ",") -> Iterator[Record]:
    """Legacy function to iterate CSV records."""
    source = CsvSource(csv_path, delimiter=delimiter)
    return source.iter_records()


def read_csv(csv_path: Path, delimiter: str = ",") -> list[Record]:
    """Legacy function to read all CSV records."""
    source = CsvSource(csv_path, delimiter=delimiter)
    return source.read_all()

