"""Record validation and schema matching."""

import json
from typing import Any

from models import Record


class ValidationError(Exception):
    """Exception raised when a record fails validation."""


def validate_batch(records: list[Record], validator: "Validator") -> list[Record]:
    """Filter valid records, print errors for invalid ones."""
    valid_records = []
    for record in records:
        try:
            validator.validate(record)
            valid_records.append(record)
        except ValidationError as e:
            print(f"Validation error for record {record.record_id}: {e}")
    return valid_records


class Validator:
    """Base class for record validators."""

    def validate(self, record: Record) -> None:
        """Validate a record, raise ValidationError if invalid."""
        raise NotImplementedError


class FieldValidator(Validator):
    """Validate that required fields are present."""

    def __init__(self, required_fields: list[str]) -> None:
        self.required_fields = required_fields

    def validate(self, record: Record) -> None:
        """Check for presence of required fields in record data."""
        missing = [
            field for field in self.required_fields if field not in record.data
        ]
        if missing:
            raise ValidationError(f"Missing required fields: {missing}")


class SchemaValidator(Validator):
    """Validate that record matches expected types."""

    def __init__(self, schema: dict[str, type]) -> None:
        self.schema = schema

    def validate(self, record: Record) -> None:
        """Check that fields match expected types."""
        for field, expected_type in self.schema.items():
            if field not in record.data:
                continue
            value = record.data[field]
            if not isinstance(value, expected_type):
                raise ValidationError(
                    f"Field '{field}' expected type {expected_type.__name__}, got {type(value).__name__}"
                )


class RangeValidator(Validator):
    """Validate numeric fields are within allowed ranges."""

    def __init__(self, ranges: dict[str, tuple[int | float, int | float]]) -> None:
        """ranges: {field: (min, max), ...}"""
        self.ranges = ranges

    def validate(self, record: Record) -> None:
        """Check numeric fields are within ranges."""
        for field, (min_val, max_val) in self.ranges.items():
            if field not in record.data:
                continue
            value = record.data[field]
            if not isinstance(value, (int, float)):
                raise ValidationError(f"Field '{field}' is not numeric")
            if not (min_val <= value <= max_val):
                raise ValidationError(
                    f"Field '{field}' value {value} not in range [{min_val}, {max_val}]"
                )


class CompositeValidator(Validator):
    """Combine multiple validators."""

    def __init__(self, validators: list[Validator]) -> None:
        self.validators = validators

    def validate(self, record: Record) -> None:
        """Run all validators."""
        for validator in self.validators:
            validator.validate(record)


# Built-in validators
__validators: dict[str, Validator] = {}


def register(name: str, validator: Validator) -> None:
    """Register a validator by name."""
    __validators[name] = validator


def get_validator(name: str) -> Validator:
    """Retrieve a registered validator."""
    if name not in __validators:
        raise ValueError(f"Unknown validator '{name}'")
    return __validators[name]


def validate(record: Record, validator_name: str) -> None:
    """Validate a record with a named validator."""
    get_validator(validator_name).validate(record)
EOF

cat > src/transform.py << 'EOF'
"""Data transformation pipeline."""

import re
import logging
from typing import Any, Callable

logger = logging.getLogger(__name__)

# Registry of named transforms
_transforms: dict[str, Callable[[dict[str, Any]], dict[str, Any] | None]] = {}


def register(name: str, fn: Callable[[dict[str, Any]], dict[str, Any] | None]) -> None:
    """Register a named transform function."""
    _transforms[name] = fn


def get_transform(name: str) -> Callable[[dict[str, Any]], dict[str, Any] | None] | None:
    """Look up a registered transform by name."""
    return _transforms.get(name)


def apply_transforms(record_data: dict[str, Any], transform_names: list[str]) -> dict[str, Any] | None:
    """Apply a list of named transforms to a record's data dict."""
    current = record_data
    for name in transform_names:
        fn = _transforms.get(name)
        if fn is None:
            logger.warning(f"Unknown transform: {name}")
            continue
        result = fn(current)
        if result is None:
            return None  # filtered out
        current = result
    return current


def compose(*fns: Callable[[dict[str, Any]], dict[str, Any] | None]) -> Callable[[dict[str, Any]], dict[str, Any] | None]:
    """Compose multiple transform functions into a single function."""
    def composed(data: dict[str, Any]) -> dict[str, Any] | None:
        current = data
        for fn in fns:
            if current is None:
                return None
            current = fn(current)
        return current
    return composed


# ---- Built-in transforms ----


def lowercase_email(data: dict[str, Any]) -> dict[str, Any]:
    if "email" in data:
        data["email"] = data["email"].lower()
    return data


register("lowercase_email", lowercase_email)


def trim_whitespace(data: dict[str, Any]) -> dict[str, Any]:
    for key, value in data.items():
        if isinstance(value, str):
            data[key] = value.strip()
    return data


register("trim_whitespace", trim_whitespace)


def anonymize_ip(data: dict[str, Any]) -> dict[str, Any]:
    if "ip_address" in data:
        # Keep first 3 octets only
        parts = data["ip_address"].split(".")
        if len(parts) == 4:
            data["ip_address"] = ".".join(parts[:3]) + ".0"
    return data


register("anonymize_ip", anonymize_ip)


def parse_currency(data: dict[str, Any]) -> dict[str, Any]:
    """Convert currency strings to float."""
    for key, value in data.items():
        if isinstance(value, str) and value.startswith("$"):
            # Remove $ and commas, convert to float
            try:
                data[key] = float(value.replace("$", "").replace(",", ""))
            except ValueError:
                pass
    return data


register("parse_currency", parse_currency)


def filter_by_country(data: dict[str, Any]) -> dict[str, Any] | None:
    """Filter record to U.S. only."""
    if data.get("country") in ("US", "USA", "United States"):
        return data
    return None


register("filter_by_country", filter_by_country)


def validate_schema(data: dict[str, Any]) -> dict[str, Any]:
    """Ensure required fields exist."""
    # Define required fields based on a sample schema
    required = ["id", "timestamp"]
    for field in required:
        if field not in data:
            data[field] = None
    return data


register("validate_schema", validate_schema)


def extract_domain(data: dict[str, Any]) -> dict[str, Any]:
    """Extract domain from email addresses."""
    if "email" in data:
        email = data["email"]
        match = re.search(r"@(.+)$", email)
        if match:
            data["email_domain"] = match.group(1)
    return data


register("extract_domain", extract_domain)

