"""Simple scheduler for periodic ingestion jobs."""

import time
import threading
from typing import Any
from dataclasses import dataclass, field


@dataclass
class Job:
    name: str
    schedule: str = "1h"  # simplified: 1h, 30m, etc.
    enabled: bool = True
    run_count: int = 0
    last_run: float = field(default_factory=lambda: 0.0)

    def interval_seconds(self) -> int:
        """Convert schedule string to seconds."""
        if self.schedule.endswith("h"):
            return int(self.schedule[:-1]) * 3600
        elif self.schedule.endswith("m"):
            return int(self.schedule[:-1]) * 60
        else:
            return 3600

    def is_due(self) -> bool:
        """Check if job is due to run."""
        if not self.enabled:
            return False
        return (time.time() - self.last_run) >= self.interval_seconds()

    def execute(self) -> None:
        """Run the job."""
        self.last_run = time.time()
        self.run_count += 1
        print(f"Executing job: {self.name}")

    def status(self) -> dict[str, Any]:
        """Return job status dict."""
        return {
            "name": self.name,
            "enabled": self.enabled,
            "schedule": self.schedule,
            "run_count": self.run_count,
            "last_run": self.last_run,
            "next_run": self.last_run + self.interval_seconds()
            if self.enabled
            else None,
        }


_jobs: dict[str, Job] = {}


def add_job(name: str, schedule: str = "1h", enabled: bool = True) -> Job:
    """Register a new scheduled job."""
    job = Job(name=name, schedule=schedule, enabled=enabled)
    _jobs[name] = job
    return job


def remove_job(name: str) -> None:
    """Remove a scheduled job."""
    _jobs.pop(name, None)


def list_jobs() -> list[dict[str, Any]]:
    """Return list of job statuses."""
    return [job.status() for job in _jobs.values()]


def run_pending() -> None:
    """Execute all jobs that are due."""
    for job in _jobs.values():
        if job.is_due():
            job.execute()


def run_loop(interval: int = 60) -> None:
    """Run scheduler loop, checking for due jobs every interval seconds."""
    while True:
        run_pending()
        time.sleep(interval)


def start_scheduler_thread(interval: int = 60) -> threading.Thread:
    """Start scheduler in a background thread."""
    thread = threading.Thread(target=run_loop, args=(interval,), daemon=True)
    thread.start()
    return thread
