"""Data warehouse writer with buffered output."""

import csv
import json
import io
import logging
import os
import time
from typing import Any

from .models import Record

logger = logging.getLogger(__name__)


class BaseWriter:
    def __init__(self, output_path: str, buffer_size: int = 100) -> None:
        self.output_path = output_path
        self.buffer_size = buffer_size
        self._buffer: list[Record] = []
        self._total_written = 0

    def write_record(self, record: Record) -> None:
        self._buffer.append(record)
        if len(self._buffer) >= self.buffer_size:
            self.flush()

    def write_batch(self, records: list[Record]) -> None:
        for record in records:
            self.write_record(record)

    def flush(self) -> None:
        raise NotImplementedError

    def close(self) -> None:
        if self._buffer:
            self.flush()

    @property
    def total_written(self) -> int:
        return self._total_written

    def __enter__(self) -> "BaseWriter":
        return self
    def __exit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        self.close()


class JsonWriter(BaseWriter):
    def __init__(self, output_path: str, buffer_size: int = 100, pretty: bool = False) -> None:
        super().__init__(output_path, buffer_size)
        self.pretty = pretty
        self._first_write = True
        # Initialize the file with an opening bracket
        with open(self.output_path, "w") as f:
            f.write("[\n")

    def flush(self) -> None:
        if not self._buffer:
            return

        with open(self.output_path, "a") as f:
            for record in self._buffer:
                data = record.to_dict()
                if not self._first_write:
                    f.write(",\n")
                if self.pretty:
                    f.write(json.dumps(data, indent=2, default=str))
                else:
                    f.write(json.dumps(data, default=str))
                self._first_write = False
            self._total_written += len(self._buffer)
            self._buffer.clear()

    def close(self) -> None:
        if self._buffer:
            self.flush()
        with open(self.output_path, "a") as f:
            f.write("\n]\n")


def write_json(records: list[Record], output_path: str, pretty: bool = False) -> None:
    """Write records to a JSON file."""
    if os.path.exists(output_path):
        os.remove(output_path)
    with JsonWriter(output_path, 1, pretty) as writer:
        writer.write_batch(records)


class CsvWriter(BaseWriter):
    def __init__(self, output_path: str, buffer_size: int = 100) -> None:
        super().__init__(output_path, buffer_size)

    def flush(self) -> None:
        if not self._buffer:
            return

        file_exists = os.path.exists(self.output_path)
        with open(self.output_path, "a", newline="") as f:
            if not file_exists:
                # Write header
                sample_record = self._buffer[0]
                headers = list(sample_record.to_dict().keys())
                writer = csv.writer(f)
                writer.writerow(headers)

            writer = csv.writer(f)
            for record in self._buffer:
                data = record.to_dict()
                row = [str(v) for v in data.values()]
                writer.writerow(row)
            self._total_written += len(self._buffer)
            self._buffer.clear()


def write_csv(records: list[Record], output_path: str) -> None:
    """Write records to a CSV file."""
    if os.path.exists(output_path):
        os.remove(output_path)
    with CsvWriter(output_path, 1) as writer:
        writer.write_batch(records)


class BatchResult:
    def __init__(self) -> None:
        self.success_count = 0
        self.failure_count = 0

    def add_success(self) -> None:
        self.success_count += 1

    def add_failure(self) -> None:
        self.failure_count += 1

    def summary(self) -> dict[str, int]:
        return {"success": self.success_count, "failure": self.failure_count}
